import { readFileSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const packageDirectory = dirname(dirname(fileURLToPath(import.meta.url)));
const tracked = join(packageDirectory, "worker-configuration.d.ts");
const candidate = join(packageDirectory, `.worker-configuration.check-${process.pid}.d.ts`);
const normalizeCommandComment = (source) =>
  source.replace(
    /^\/\/ Generated by Wrangler by running `[^`]+` \(hash: ([^)]+)\)$/m,
    "// Generated by Wrangler (hash: $1)",
  );

try {
  const generated = spawnSync(
    "pnpm",
    ["exec", "wrangler", "types", "-c", "wrangler.private.jsonc", candidate],
    { cwd: packageDirectory, stdio: "inherit" },
  );
  if (generated.status !== 0) {
    process.exitCode = generated.status ?? 1;
    throw new Error("Wrangler type generation failed");
  }
  if (
    normalizeCommandComment(readFileSync(candidate, "utf8")) !==
    normalizeCommandComment(readFileSync(tracked, "utf8"))
  ) {
    console.error(
      "worker-configuration.d.ts is stale; run pnpm --filter @gadgets/codex-relay types:generate",
    );
    process.exitCode = 1;
  }
} finally {
  rmSync(candidate, { force: true });
}
